using Godot;
using System;
using Settings=Godot.Collections.Dictionary;

public partial class TransformationCanvasOperations : RefCounted
{
    private static Resource? Document(Control owner)=>owner.Get("document").As<Resource>();
    private static Vector2 Origin(Control owner)=>owner.Call("origin").AsVector2();
    public void ready(Control owner){var engine=owner.Get("repair_tool").AsGodotObject().Get("engine").As<Node>();if(engine.GetParent()==null)owner.AddChild(engine);}
    public void draw(Control owner)
    {
        var document=Document(owner);if(document==null)return;float zoom=owner.Get("zoom").AsSingle();var origin=Origin(owner);bool preview=owner.Get("previewing").AsBool();if(owner.Get("show_grid").AsBool()){float step=32*zoom;if(step>=8){var rect=new Rect2(origin,(Vector2)document.Get("canvas_size").AsVector2I()*zoom).Intersection(new Rect2(Vector2.Zero,owner.Size));for(int x=(int)Math.Floor((rect.Position.X-origin.X)/step);x<(int)Math.Ceiling((rect.End.X-origin.X)/step);x++)owner.DrawLine(new Vector2(origin.X+x*step,rect.Position.Y),new Vector2(origin.X+x*step,rect.End.Y),new Color(1,1,1,.09f));for(int y=(int)Math.Floor((rect.Position.Y-origin.Y)/step);y<(int)Math.Ceiling((rect.End.Y-origin.Y)/step);y++)owner.DrawLine(new Vector2(rect.Position.X,origin.Y+y*step),new Vector2(rect.End.X,origin.Y+y*step),new Color(1,1,1,.09f));}}
        var onion=owner.Get("onion").As<Resource>();if(onion!=null&&!preview){var texture=onion.Get("texture").As<Texture2D>();if(texture!=null){var transform=new Transform2D(0,origin).ScaledLocal(Vector2.One*zoom)*onion.Call("local_transform").AsTransform2D();owner.DrawSetTransformMatrix(transform);owner.DrawTextureRect(texture,new Rect2(Vector2.Zero,onion.Get("dimensions").AsVector2()),false,new Color(.7f,.85f,1,.2f));owner.DrawSetTransformMatrix(Transform2D.Identity);}}var selected=owner.Get("selected").AsGodotArray();if(!preview&&selected.Count==1){var layer=document.Call("layer_for_id",selected[0]).As<Resource>();if(layer!=null){var point=origin+layer.Call("local_transform").AsTransform2D()*(layer.Get("dimensions").AsVector2()*owner.Get("pivot_uv").AsVector2())*zoom;owner.DrawCircle(point,7,new Color("11212b"));owner.DrawArc(point,6,0,Mathf.Tau,24,new Color("ffd18a"),1.5f,true);owner.DrawLine(point-new Vector2(10,0),point+new Vector2(10,0),new Color("ffd18a"));owner.DrawLine(point-new Vector2(0,10),point+new Vector2(0,10),new Color("ffd18a"));}}
    }
    public bool input(Control owner,InputEvent input)
    {
        var document=Document(owner);if(document==null)return true;bool preview=owner.Get("previewing").AsBool();if(preview){if(input is InputEventMouseButton button&&button.ButtonIndex==MouseButton.Left&&!Input.IsKeyPressed(Key.Space)){owner.AcceptEvent();return true;}if(input is InputEventKey pressed&&pressed.Pressed)return true;}string tool=owner.Get("tool").AsString();var selected=owner.Get("selected").AsGodotArray();if(tool is "pivot" or "reveal_path"&&selected.Count==1){var layer=document.Call("layer_for_id",selected[0]).As<Resource>();if(layer!=null&&document.Call("can_edit",layer).AsBool()){Vector2 Uv(Vector2 at)=>(layer.Call("local_transform").AsTransform2D().AffineInverse()*owner.Call("to_document",at).AsVector2()/layer.Get("dimensions").AsVector2()).Clamp(Vector2.Zero,Vector2.One);if(input is InputEventMouseButton mouse&&mouse.ButtonIndex==MouseButton.Left){var uv=Uv(mouse.Position);if(tool=="reveal_path"){if(mouse.Pressed)owner.EmitSignal("reveal_point",uv);}else if(mouse.Pressed){owner.Set("pivot_before",owner.Get("pivot_uv"));owner.Set("_drag","pivot");owner.EmitSignal("gesture_started");owner.EmitSignal("pivot_changed",uv);}else if(owner.Get("_drag").AsString()=="pivot"){owner.Set("_drag","");owner.EmitSignal("gesture_finished");}owner.GrabFocus();owner.QueueRedraw();owner.AcceptEvent();return true;}if(input is InputEventMouseMotion motion&&owner.Get("_drag").AsString()=="pivot"){owner.EmitSignal("pivot_changed",Uv(motion.Position));owner.QueueRedraw();owner.AcceptEvent();return true;}if(input is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape&&owner.Get("_drag").AsString()=="pivot"){owner.Set("_drag","");owner.EmitSignal("pivot_changed",owner.Get("pivot_before"));owner.EmitSignal("gesture_cancelled");owner.AcceptEvent();return true;}}}
        if(!preview&&tool=="move"&&input is InputEventMouseButton click&&click.ButtonIndex==MouseButton.Left&&click.Pressed&&!click.ShiftPressed&&!click.CtrlPressed){var point=owner.Call("to_document",click.Position).AsVector2();var bounds=owner.Call("selection_bounds").AsRect2();float zoom=owner.Get("zoom").AsSingle();var screen=new Rect2(Origin(owner)+bounds.Position*zoom,bounds.Size*zoom);bool overHandle=owner.Call("_rotation_handle",screen).AsVector2().DistanceTo(click.Position)<12;foreach(var handle in owner.Call("_handles",screen).AsGodotArray())overHandle|=handle.AsVector2().DistanceTo(click.Position)<12;if(selected.Count>0&&bounds.HasPoint(point)&&!overHandle&&owner.Call("hit",point).AsGodotObject()==null){owner.Set("_start",point);owner.Set("_last",point);owner.Set("_moved",false);owner.Set("_bounds",bounds);owner.Call("_begin_transform","move");owner.GrabFocus();owner.AcceptEvent();return true;}}return false;
    }
    public bool transform(Control owner,Vector2 point,bool constrained,bool control)
    {
        var originals=owner.Get("_originals").AsGodotArray();if(owner.Get("_drag").AsString()!="rotate"||originals.Count!=1)return false;var entry=originals[0].AsGodotDictionary();var pivot=entry["dimensions"].AsVector2()*owner.Get("pivot_uv").AsVector2();var center=entry["world"].AsTransform2D()*pivot;float angle=(owner.Get("_start").AsVector2()-center).AngleTo(point-center);if(constrained||owner.Get("snapping").AsBool()!=control)angle=Mathf.Snapped(angle,Mathf.Pi/12);var layer=entry["layer"].AsGodotObject();layer.Set("rotation",entry["rotation"].AsDouble()+angle);var rotated=layer.Call("local_transform").AsTransform2D();layer.Set("position",layer.Get("position").AsVector2()+center-rotated*pivot);owner.Set("_moved",true);owner.EmitSignal("gesture_changed");return true;
    }
}
